532:static PDFSubtypeConformance pdfConformanceFromString(GooString *pdfSubtypeVersion) {
533:  const std::regex regex("PDF/(?:A|X|VT|E|UA)-[[:digit:]]([[:alpha:]]+)");
534:  std::smatch match;
535:  const std::string pdfsubver = pdfSubtypeVersion->toStr();
536:  PDFSubtypeConformance pdfConf = subtypeConfNone;
537:
538:  // match contains the PDF conformance (A, B, G, N, P, PG or U)
539:  if (std::regex_search(pdfsubver, match, regex)) {
540:    GooString *conf = new GooString(match.str(1));
541:    // Convert to lowercase as the conformance may appear in both cases
542:    conf->lowerCase();
543:    if (conf->cmp("a")==0) {
544:      pdfConf = subtypeConfA;
545:    } else if (conf->cmp("b")==0) {
546:      pdfConf = subtypeConfB;
547:    } else if (conf->cmp("g")==0) {
548:      pdfConf = subtypeConfG;
549:    } else if (conf->cmp("n")==0) {
550:      pdfConf = subtypeConfN;
551:    } else if (conf->cmp("p")==0) {
552:      pdfConf = subtypeConfP;
553:    } else if (conf->cmp("pg")==0) {
554:      pdfConf = subtypeConfPG;
555:    } else if (conf->cmp("u")==0) {
556:      pdfConf = subtypeConfU;
557:    } else {
558:      pdfConf = subtypeConfNone;
559:    }
560:    delete conf;
561:  }
562:
563:  return pdfConf;
564:}
