566:void PDFDoc::extractPDFSubtype() {
567:  pdfSubtype = subtypeNull;
568:  pdfPart = subtypePartNull;
569:  pdfConformance = subtypeConfNull;
570:
571:  GooString *pdfSubtypeVersion = nullptr;
572:  // Find PDF InfoDict subtype key if any
573:  if ((pdfSubtypeVersion = getDocInfoStringEntry("GTS_PDFA1Version"))) {
574:    pdfSubtype = subtypePDFA;
575:  } else if ((pdfSubtypeVersion = getDocInfoStringEntry("GTS_PDFEVersion"))) {
576:    pdfSubtype = subtypePDFE;
577:  } else if ((pdfSubtypeVersion = getDocInfoStringEntry("GTS_PDFUAVersion"))) {
578:    pdfSubtype = subtypePDFUA;
579:  } else if ((pdfSubtypeVersion = getDocInfoStringEntry("GTS_PDFVTVersion"))) {
580:    pdfSubtype = subtypePDFVT;
581:  } else if ((pdfSubtypeVersion = getDocInfoStringEntry("GTS_PDFXVersion"))) {
582:    pdfSubtype = subtypePDFX;
583:  } else {
584:    pdfSubtype = subtypeNone;
585:    pdfPart = subtypePartNone;
586:    pdfConformance = subtypeConfNone;
587:    return;
588:  }
589:
590:  // Extract part from version string
591:  pdfPart = pdfPartFromString(pdfSubtype, pdfSubtypeVersion);
592:
593:  // Extract conformance from version string
594:  pdfConformance = pdfConformanceFromString(pdfSubtypeVersion);
595:
596:  delete pdfSubtypeVersion;
597:}
